const express = require('express');

const PORT = process.env.PORT || 3000;
const DRAIN_DEADLINE_MS = 5000;

// True once SIGTERM/SIGINT has been received and we are draining.
let shuttingDown = false;

const app = express();

// Drain guard: while shutting down, any request that arrives on an
// already-open (e.g. keep-alive) socket cannot be served normally.
// Respond 503 and tell the client to close the connection.
app.use((req, res, next) => {
  if (shuttingDown) {
    res.set('Connection', 'close');
    return res.status(503).json({ error: 'shutting down' });
  }
  next();
});

app.get('/health', (req, res) => res.status(200).send('ok'));

app.get('/slow', (req, res) => {
  setTimeout(() => {
    // In-flight requests are allowed to complete even during drain.
    res.status(200).send('slow ok');
  }, 2000);
});

const server = app.listen(PORT, () => {
  console.log(`server listening on :${server.address().port} (pid ${process.pid})`);
});

function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`[${signal}] draining: stop accepting new connections`);

  // 1. Stop accepting new connections; wait for in-flight requests.
  server.close(() => {
    console.log('drain complete, exiting 0');
    process.exit(0);
  });

  // Close idle keep-alive sockets so they don't hold the drain open
  // (Node >= 18.2). Requests already being served are untouched.
  if (typeof server.closeIdleConnections === 'function') {
    server.closeIdleConnections();
  }

  // 2. Force-exit if the drain deadline expires.
  const deadline = setTimeout(() => {
    console.error(`drain deadline (${DRAIN_DEADLINE_MS}ms) exceeded, force exit`);
    process.exit(1);
  }, DRAIN_DEADLINE_MS);
  deadline.unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
