// Prove: request pipelined on an already-open (busy) socket during drain -> 503 + Connection: close
const net = require('net');
const { spawn } = require('child_process');
const srv = spawn('node', ['server.js'], { env: { ...process.env, PORT: '3466' } });
srv.stdout.on('data', d => process.stdout.write('[srv] ' + d));
srv.stderr.on('data', d => process.stderr.write('[srv!] ' + d));
setTimeout(() => {
  const sock = net.connect(3466, '127.0.0.1', () => {
    sock.write('GET /slow HTTP/1.1\r\nHost: x\r\n\r\n');           // in-flight, takes 2s
    setTimeout(() => {
      srv.kill('SIGTERM');                                          // drain starts
      console.log('[probe] SIGTERM sent while /slow in flight');
      setTimeout(() => {
        sock.write('GET /health HTTP/1.1\r\nHost: x\r\nConnection: keep-alive\r\n\r\n'); // pipelined on same socket
      }, 200);
    }, 300);
  });
  let buf = '';
  sock.on('data', d => {
    buf += d.toString();
    const parts = buf.split('\r\n\r\n');
    if (parts.length >= 2 && parts[parts.length - 2] !== undefined) {}
    // crude: report each status line seen
    for (const m of buf.matchAll(/HTTP\/1\.1 (\d+)/g)) console.log('[probe] got:', m[0]);
    if ((buf.match(/HTTP\/1\.1/g) || []).length === 2) {
      const ok503 = /HTTP\/1\.1 503[\s\S]*Connection: close/i.test(buf.split('200')[1] || '');
      console.log('[probe] RESULT:', ok503 ? 'PASS (503 + Connection: close)' : 'FAIL:\n' + buf);
      sock.end();
      process.exit(ok503 ? 0 : 1);
    }
  });
}, 500);
EOF
